sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float scale;
uniform float angle;
uniform float2 offset;
uniform float mask;
uniform float alpha;
uniform float fill;
uniform float sampling;
half4 main(float2 coord) {
    float2 c = size * 0.5;
    float a = radians(angle);
    float2 v = coord - c - offset;
    float2 p = c + float2(cos(a) * v.x + sin(a) * v.y, cos(a) * v.y - sin(a) * v.x) / max(scale, 0.01);
    if (sampling < 0.5) p = floor(p) + 0.5;
    half4 own = image.eval(coord);
    half4 moved = image.eval(p) * half(clamp(alpha, 0.0, 1.0));
    half4 color = moved + own * half(clamp(fill, 0.0, 1.0)) * (1.0 - moved.a);
    if (mask > 0.5) color *= own.a;
    return color;
}
